type ValuesEditor interface {
	AppendValues(xs ...bob.Expression)
	RowCount() int
	SetValue(row, col int, x bob.Expression)
	AppendOrder(x bob.Expression)
	ClearOrderBy()
	SetLimit(x any)
}

type valuesEditor struct {
	q         *valuesState
	ownedRows bool
}

func (s *valuesState) open() *valuesEditor {
	s.RowVals = slices.Clip(s.RowVals)
	s.OrderBy.Expressions = slices.Clip(s.OrderBy.Expressions)

	return &valuesEditor{q: s}
}

func (e *valuesEditor) close() {
	e.q = nil
}

func (s *valuesState) apply(ms []bob.Mod[ValuesEditor]) {
	if len(ms) == 0 {
		return
	}
	e := s.open()
	defer e.close()
	bob.Mods[ValuesEditor](ms).Edit(e)
}

func (s valuesState) WithMods(ms []bob.Mod[ValuesEditor]) bob.QuerySource[ValuesEditor] {
	s.apply(ms)
	return &s
}

func NewValuesSource(ms ...bob.Mod[ValuesEditor]) bob.QuerySource[ValuesEditor] {
	s := new(valuesState)
	s.apply(ms)
	return s
}

func NewValues(
	hooks []bob.QueryHook[ValuesEditor],
	ms ...bob.Mod[ValuesEditor],
) bob.QueryBuilder[ValuesEditor] {
	return bob.NewQueryBuilder(NewValuesSource(ms...), Dialect, bob.QueryTypeValues, hooks...)
}

func (e *valuesEditor) AppendValues(xs ...bob.Expression) {
	e.q.AppendValues(xs...)
}

func (e *valuesEditor) RowCount() int {
	return len(e.q.RowVals)
}

func (e *valuesEditor) SetValue(row, col int, x bob.Expression) {
	if !e.ownedRows {
		e.q.RowVals = internal.CloneRows(e.q.RowVals)
		e.ownedRows = true
	}
	e.q.RowVals[row][col] = x
}

func (e *valuesEditor) AppendOrder(x bob.Expression) {
	e.q.AppendOrder(x)
}

func (e *valuesEditor) ClearOrderBy() {
	e.q.ClearOrderBy()
}

func (e *valuesEditor) SetLimit(x any) {
	e.q.SetLimit(x)
}
